export type MessagerType =
| "change_features"
| "send_api_action"

export interface Messager {
    type: MessagerType;
    payload?: any;
};

export interface SendRequestMessager {
    type: MessagerType;
    config: any;
};

const storage = {
    get: async <T>(key: string): Promise<T | null> => {
        try {
            const result = await chrome.storage.local.get([key]);
            return result[key] || null;
        } catch (error) {
            console.error('[storage get]', error);
            return null;
        }
    },

    set: async <T>(key: string, value: T): Promise<void> => {
        try {
            await chrome.storage.local.set({ [key]: value });
        } catch (error) {
            console.error('[storage set]', error);
        }
    },

    remove: async (key: string): Promise<void> => {
        try {
            await chrome.storage.local.remove(key);
        } catch (error) {
            console.error('[storage remove]', error);
        }
    }
};

export default storage;

import type { Messager, SendRequestMessager } from "@utils/types/messager";

export const sendMessage = async (message: Messager): Promise<any> => {
  try {
    const response = await chrome.runtime.sendMessage(message);
    return response;
  } catch (error) {
    console.error('[sendMessage]', error);
  }
};

export const sendRequestMessage = async (message: SendRequestMessager): Promise<any> => {
  try {
    const response = await chrome.runtime.sendMessage(message);
    return response;
  } catch (error) {
    console.error('[sendRequestMessage]', error);
  }
};

export const broadcastToTabs = async (message: Messager): Promise<void> => {
  try {
    const tabs = await chrome.tabs.query({});
    await Promise.allSettled(
      tabs.map(tab => 
        tab.id ? chrome.tabs.sendMessage(tab.id, message) : Promise.resolve()
      )
    );
  } catch (error) {
    console.error('[broadcastToTabs]', error);
  }
};

import defaultConfig from "@assets/config/default";
import useExtensionStore from "@stores/extension";
import { Messager } from "@utils/types/messager";

export type ContentScriptNames = typeof contentScriptNamesData[number];

interface ManageScriptData {
    name: ContentScriptNames;
    run: () => Promise<boolean>;
};

export const contentScriptNamesData = [
  "example",
] as const;

const manageScript = async ({ name, run }: ManageScriptData) => {
    useExtensionStore.subscribe(async (state) => {
        if (state.extension.features[name] === true) {
            try {
                console.info(`[manageScript] mode: ${defaultConfig.mode} version: ${defaultConfig.version}\n\n\n\n`);
                    let startedIn = Date.now();
                    console.log(`[manageScript] (${name}) Starting script execution`);

                    console.group(`[${name} logs]`)
                    const status = await run();
                    console.groupEnd();

                    let endIn = Date.now();
                    console.log(`[manageScript] (${name}) Finished in ${(endIn - startedIn) / 1000}s`);
                    console.log(`[manageScript] (${name}) status: ${status ? "successful" : "unsuccessful"}`);
            } catch (error){
                console.log(`[manageScript] (${name}) Execution error`, error);
            };
        };
    });

    chrome.runtime.onMessage.addListener((message: Messager, _sender, sendResponse) => {
        if (message.payload.name === name){
            if (message.type === "change_features"){
              window.location.reload()
              sendResponse({ success: true })
              return true;
            }
        };
        return false;
      });
};

export default manageScript;

import { createRoot } from "react-dom/client";

interface DomServiceOptions {
  dynamicId?: boolean;
}

const domService = {
  injectReactRoot: async (children: React.ReactNode, options?: DomServiceOptions) => {
    let reactContainerId = "uailab-react-root";
    if (options?.dynamicId) {
      const buffer = new Uint8Array(3);
      crypto.getRandomValues(buffer);
      const token = Array.from(buffer, byte => byte.toString(16).padStart(2, '0')).join('');
      reactContainerId += `-${token}`;
    }
    let reactContainer = document.getElementById(reactContainerId);
    if (!reactContainer) {
      reactContainer = document.createElement("div");
      reactContainer.id = reactContainerId;
      document.body.appendChild(reactContainer);
    }
    const root = createRoot(reactContainer);
    root.render(children);
  }
};

export default domService;

import axios from 'axios';
import defaultConfig from '@assets/config/default';
import storage from './storage.ts';

const createApi = async () => {
  const token = (await storage.get("token")) || "";

  return axios.create({
    baseURL: defaultConfig.baseURL,
    headers: {
      'controlAccess': import.meta.env.VITE_CONTROL_ACCESS,
      'Content-Type': 'application/json',
      'authorization': token as string,
    }
  });
};

export default createApi;

