import { persist } from "zustand/middleware";
import { create } from "zustand";

import { sendMessage } from "@utils/functions/messager";
import storage from "@utils/functions/storage";
import defaultValues from "./defaultValues";
import { ExtensionStore } from "./types";

const useExtensionStore = create<ExtensionStore>()(
  persist(
    (set) => ({
      setExtension: (extension) => set({ extension }),
      extension: defaultValues,
      setFeatureStatus: async (featureName, status) => {
        set((state) => {
          const updatedExtension = { ...state.extension };
          updatedExtension.features[featureName] = status;
          return { extension: updatedExtension };
        });

        await sendMessage({ type: "change_features", payload: {
          name: featureName
        } });
      },
      updateExtension: (partialExtension) => set((state) => ({
        extension: { ...state.extension, ...partialExtension },
      })),
    }),
    {
      name: "extension-store",
      storage: {
        getItem: async (key: string) => {
          const result = await storage.get<string>(key);
          return result ? (JSON.parse(result) as { state: ExtensionStore }) : null;
        },
        setItem: async (key: string, value: { state: ExtensionStore }) => {
          await storage.set(key, JSON.stringify(value));
        },
        removeItem: async (key: string) => {
          await storage.remove(key);
        },
      },
    }
  )
);

export default useExtensionStore;

export interface ExtensionData {
    features: Record<string, boolean>;
};

export interface ExtensionStore {
  extension: ExtensionData;
  setExtension: (extension: ExtensionData) => void;
  setFeatureStatus: (featureName: string, status: boolean) => void;
  updateExtension: (partialExtension: Partial<ExtensionData>) => void;
};

