import createApi from "@utils/functions/api";
import { broadcastToTabs } from "@utils/functions/messager";
import { Messager, SendRequestMessager } from "@utils/types/messager";
import axios, { AxiosRequestConfig } from "axios";

chrome.runtime.onInstalled.addListener(() => {
    console.log("[background] Extension installed");
});

chrome.runtime.onMessage.addListener((message: Messager | SendRequestMessager, _sender, sendResponse) => {
    (async () => {
      try {
        switch (message.type) {
          case "change_features":
            await broadcastToTabs(message);
            sendResponse({ success: true });
            break;
          case "send_api_action":
            try {
                const response = await (await createApi())((message as SendRequestMessager).config as AxiosRequestConfig);
                sendResponse(response.data);
            } catch (error){
                if (axios.isAxiosError(error) && error.response) {
                    return sendResponse({ error: error.response.data.message || 'Unknown error' });
                };
                sendResponse({ success: false, error });
            };
            break;
          default:
            sendResponse({ error: "Unknown message type" });
            break;
        }
      } catch (error) {
        console.error('[background onMessage]', error);
        sendResponse({ success: false, error });
      }
    })();

    return true;
  });

import { manageActionError } from '@utils/functions/action';
import createApi from '@utils/functions/api';

import type { SomeResourceType, CreateData, UpdateData } from './types';
import type { TypeOrError } from '@utils/types/action';

export const createSomeResource = async (data: CreateData): TypeOrError<SomeResourceType> => {
  try {
    const response = await (await createApi()).post("/resource", data);
    return response.data;
  } catch (error) {
    return manageActionError(error);
  }
};

export const getSomeResource = async (id: string): TypeOrError<SomeResourceType> => {
  try {
    const response = await (await createApi()).get(`/resource/${id}`);
    return response.data;
  } catch (error) {
    return manageActionError(error);
  }
};

export const updateSomeResource = async (id: string, data: UpdateData): TypeOrError<SomeResourceType> => {
  try {
    const response = await (await createApi()).patch(`/resource/${id}`, data);
    return response.data;
  } catch (error) {
    return manageActionError(error);
  }
};

export const deleteSomeResource = async (id: string): TypeOrError<void> => {
  try {
    await (await createApi()).delete(`/resource/${id}`);
    return;
  } catch (error) {
    return manageActionError(error);
  }
};

import createApi from "./api";

export const setAuthToken = async (token?: string) => {
  if (token) {
    localStorage.setItem('token', token);
    (await createApi()).defaults.headers.common['authorization'] = token;
  } else {
    localStorage.removeItem('token');
    delete (await createApi()).defaults.headers.common['authorization'];
  }
};
